/bin/zsh -lc "python - <<'PY'
import urllib.request,re
urls=['https://ceee.hhu.edu.cn/2025/0905/c12558a306844/page.htm','https://www.ee.sdu.edu.cn/xygk/xyjj.htm','https://yjsy.ncepu.edu.cn/zsxx/sszsxx/36c4462386704afdaed3e025c6155d7c.htm']
for u in urls:
 try:
  s=urllib.request.urlopen(u,timeout=20).read().decode('utf-8')
  print('\\nURL',u)
  if 'hhu' in u: print('\\n'.join(re.findall(r'["'^'"\\s<>\"\\x27]*(?:\\.pdf|\\.jpg|\\.png)["'^'"\\s<>\"\\x27]*',s)))
  else:
   s=re.sub(r'<script\\b["'^>]*>.*?</script>'"','',s,flags=re.S)
   t=re.sub(r'<["'^>]*>'"',' ',s)
   t=re.sub(r'\\s+',' ',t)
   print(t[-13000:])
 except Exception as e: print(e)
PY"

